fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    let mut result = Vec::with_capacity(arr.len());
    if min_val <= max_val {
        for &v in arr.iter() {
            if v < min_val {
                result.push(min_val);
            } else if v > max_val {
                result.push(max_val);
            } else {
                result.push(v);
            }
        }
    } else {
        for _ in arr.iter() {
            result.push(max_val);
        }
    }
    result
}